from heapq import heappop, heappush

class Solution:
    def isUgly(self, n: int) -> bool:
        if n <= 0:
            return False
        heap, seen = [1], {1}
        while heap:
            value = heappop(heap)
            if value >= n:
                return value == n
            for prime in (2, 3, 5):
                candidate = value * prime
                if candidate not in seen:
                    seen.add(candidate)
                    heappush(heap, candidate)
        return False
